package ma.mystix.mobile.devicehub

/**
 * What Android declares about the terminal (android.os.Build and the application), nothing more.
 * No IMEI, no hardware serial number: the terminal is identified by [installationId], a random UUID generated by
 * Atelys at first start and deleted with the application data.
 */
data class DeviceDescriptor(
    val installationId: String,
    val manufacturer: String,
    val brand: String,
    val model: String,
    val product: String,
    val androidRelease: String,
    val sdkInt: Int,
    val buildId: String,
    val appVersion: String,
) {
    /** The physical model. An Android update keeps it; another terminal (or a restored backup) changes it. */
    val fingerprint: String
        get() = listOf(manufacturer, model, product).joinToString("|") { it.trim().lowercase() }
}

/** How a capability is known. Only [DETECTED] comes from a check made on this terminal. */
enum class CapabilitySource { DETECTED, DECLARED_BY_PROFILE }

/**
 * A capability found on the terminal by the platform layer, with the evidence that supports it.
 * Ids are stable strings such as [CapabilityIds.KEY_EVENTS]; a capability absent from the list is unknown, not absent.
 */
data class DeviceCapability(val id: String, val source: CapabilitySource, val evidence: String)

object CapabilityIds {
    /** The application receives key events (always true for an Activity; says nothing about a scanner). */
    const val KEY_EVENTS = "input.key-events"

    /** The Honeywell AIDC SDK is bundled in this build of Atelys. False in builds made without the SDK. */
    const val HONEYWELL_AIDC_SDK_BUNDLED = "honeywell.aidc.sdk-bundled"
}

/** Whether the scan service answered. [UNKNOWN] when no adapter can tell without a physical scan. */
enum class ScannerAvailability { AVAILABLE, UNAVAILABLE, UNKNOWN }

/** One detection: identity, capabilities and scanner state at a given time. */
data class DeviceSnapshot(
    val device: DeviceDescriptor,
    val capabilities: List<DeviceCapability>,
    val scannerAvailability: ScannerAvailability,
    val detectedAtMillis: Long,
) {
    fun has(capabilityId: String): Boolean = capabilities.any { it.id == capabilityId && it.source == CapabilitySource.DETECTED }

    /** What changed since [previous], to decide whether the integration must be resolved again. */
    fun changesSince(previous: DeviceSnapshot?): List<DeviceChange> {
        if (previous == null) return listOf(DeviceChange.FIRST_DETECTION)
        val changes = mutableListOf<DeviceChange>()
        if (previous.device.installationId != device.installationId) changes += DeviceChange.INSTALLATION
        if (previous.device.fingerprint != device.fingerprint) changes += DeviceChange.MODEL
        if (previous.device.sdkInt != device.sdkInt || previous.device.buildId != device.buildId) changes += DeviceChange.SYSTEM
        if (previous.device.appVersion != device.appVersion) changes += DeviceChange.APPLICATION
        if (previous.capabilities.map { it.id }.toSet() != capabilities.map { it.id }.toSet()) changes += DeviceChange.CAPABILITIES
        if (previous.scannerAvailability != scannerAvailability) changes += DeviceChange.SCANNER_AVAILABILITY
        return changes
    }
}

enum class DeviceChange { FIRST_DETECTION, INSTALLATION, MODEL, SYSTEM, APPLICATION, CAPABILITIES, SCANNER_AVAILABILITY }

/** Reads the terminal. The Android implementation reads android.os.Build and queries its scan adapters. */
fun interface DeviceDetector {
    fun detect(): DeviceSnapshot
}
